var a=`1402-afghan-biscuits`;var i=`world-1402`;var n=`NZ`;var s=`oceania`;var o=12;var r=71;var c={en:`Afghan Biscuits`,ua:`Печиво «Афган»`};var u={en:`Classic New Zealand cocoa biscuits traditionally made with cornflakes, finished with chocolate icing and walnuts. This catalog-based version uses crisp cracker crumbs in place of absent cornflakes.`,ua:`Класичне новозеландське печиво з какао, яке традиційно готують із кукурудзяними пластівцями, шоколадною глазур’ю та волоським горіхом. У цій версії відсутні пластівці замінено хрусткою крихтою крекерів.`};var l=[{en:`Preheat oven to 180°C. Cream softened butter with caster sugar until fluffy.`,ua:`Розігрійте духовку до 180°C. Розітріть м’яке масло з дрібним цукром до пухкої маси.`,t:[`creaming-butter-sugar`],m:5,i:[[`unsalted-butter`,180,`g`],[`caster-sugar`,95,`g`]]},{en:`Sift in flour and cocoa, then fold in coarsely crushed cracker crumbs to mimic the crunch of traditional cornflakes.`,ua:`Просійте борошно з какао, а потім умішайте грубо подрібнену крихту крекерів, щоб наблизити хрускіт традиційних кукурудзяних пластівців.`,t:[`mixing`,`folding-in`],m:5,i:[[`all-purpose-flour`,185,`g`],[`cocoa-powder`,24,`g`],[`cracker-crumbs`,55,`g`]]},{en:`Press 12 walnut-sized mounds onto a parchment-lined tray. Bake for 14–16 minutes, until the biscuits are set but not burned.`,ua:`Викладіть на деко з пергаментом 12 невеликих купок і злегка притисніть. Випікайте 14–16 хвилин, доки печиво схопиться, але не підгорить.`,t:[`baking`],m:16,i:[]},{en:`Cool completely before icing, about 25 minutes.`,ua:`Повністю остудіть печиво перед нанесенням глазурі, приблизно 25 хвилин.`,t:[`resting-food`],m:25,i:[]},{en:`Whisk powdered sugar with cocoa, softened butter and just enough warm water to make spreadable chocolate icing.`,ua:`Змішайте цукрову пудру з какао, м’яким маслом і невеликою кількістю теплої води до консистенції глазурі.`,t:[`mixing`],m:5,i:[[`powdered-sugar`,170,`g`],[`cocoa-powder`,15,`g`],[`unsalted-butter`,20,`g`],[`water`,25,`ml`]]},{en:`Ice the cooled biscuits and press a walnut piece into each. Allow icing to set.`,ua:`Покрийте охололе печиво глазур’ю і притисніть до кожного шматочок волоського горіха. Дайте глазурі застигнути.`,t:[`garnishing`],m:15,i:[[`walnut`,45,`g`]]}];var g={slug:a,id:i,country:`NZ`,region:s,servings:12,minutes:71,title:c,text:u,steps:l};export{n as country,g as default,i as id,r as minutes,s as region,o as servings,a as slug,l as steps,u as text,c as title};